/**
 * @distilled.cloud/daytona — Daytona SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy models
 * in `.generated-specs` (written by `scripts/convert.ts` from the three
 * OpenAPI documents mirrored at `specs/spec-mirror-daytona/specs/`).
 * Everything else in this folder is hand-written.
 *
 * One module per API tag. Platform tags (`sandbox`, `organizations`,
 * `snapshots`, …) hit `https://app.daytona.io/api`. Toolbox tags
 * (`process`, `git`, `fileSystem`, `computerUse`, …) hit the sandbox
 * toolbox proxy — configure `sandboxId` on the credentials to call them.
 * Analytics tags (`telemetry`, `usage`) hit
 * `https://analytics.app.daytona.io`.
 *
 * @example
 * ```ts
 * import * as Daytona from "@distilled.cloud/daytona";
 *
 * const sandbox = yield* Daytona.Services.sandbox.createSandbox({});
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { DaytonaProtocol, type DaytonaOpError, type DaytonaOpContext } from "./protocol.ts";
export { paginateToken } from "./pagination.ts";
export * as Retry from "./retry.ts";
export * as Services from "./services/index.ts";
